-- PREPARED MIGRATION. Applied to the synthetic local database only.
CREATE EXTENSION IF NOT EXISTS pg_jsonschema WITH SCHEMA extensions;
CREATE TABLE inventario.full_settings(
 id boolean PRIMARY KEY DEFAULT true CHECK(id), policy_version integer NOT NULL DEFAULT 1,
 groups_revision bigint NOT NULL DEFAULT 1 CHECK(groups_revision BETWEEN 1 AND 9007199254740991),
 new_ingestion boolean NOT NULL DEFAULT false, new_sessions boolean NOT NULL DEFAULT false,
 raw_history_enabled boolean NOT NULL DEFAULT false, retention_capacity_verified boolean NOT NULL DEFAULT false
);
INSERT INTO inventario.full_settings(id) VALUES(true);
CREATE TABLE inventario.full_contracts(kind text PRIMARY KEY,document jsonb NOT NULL);
ALTER TABLE inventario.instalaciones ADD COLUMN full_enabled boolean NOT NULL DEFAULT false;
CREATE TABLE inventario.full_site_permissions(
 installation_id uuid NOT NULL REFERENCES inventario.instalaciones(id),
 sede_id uuid NOT NULL REFERENCES public.sedes(id),warehouse text NOT NULL CHECK(warehouse IN ('ALMCASUARINAS','ALMDIVINO','ALMHUACACHINA','ALMCUTERVO','ALMUNIDAD')),
 PRIMARY KEY(installation_id,sede_id),UNIQUE(installation_id,warehouse)
);
CREATE TABLE inventario.full_catalog_receipts(
 installation_id uuid NOT NULL REFERENCES inventario.instalaciones(id),version integer NOT NULL,hash text NOT NULL CHECK(hash~'^[0-9a-f]{64}$'),confirmed_at timestamptz NOT NULL,
 PRIMARY KEY(installation_id,version)
);
CREATE TABLE inventario.full_commands(
 installation_id uuid NOT NULL REFERENCES inventario.instalaciones(id),operation_id uuid NOT NULL,
 action text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(installation_id,operation_id)
);
CREATE TABLE inventario.full_batches(
 id uuid PRIMARY KEY,installation_id uuid NOT NULL REFERENCES inventario.instalaciones(id),
 enterprise_id text NOT NULL,report_id text NOT NULL,source_fingerprint text NOT NULL,
 captured_at timestamptz NOT NULL CHECK(isfinite(captured_at)),finished_at timestamptz NOT NULL,downloaded_at timestamptz NOT NULL,
 master_hash text NOT NULL CHECK(master_hash~'^[0-9a-f]{64}$'),catalog_version integer NOT NULL REFERENCES inventario.versiones_catalogo(version),catalog_hash text NOT NULL,
 groups_revision bigint NOT NULL,lifecycle text NOT NULL DEFAULT 'open' CHECK(lifecycle IN ('open','closed')),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(installation_id,enterprise_id,report_id),CHECK(captured_at<=finished_at AND finished_at<=downloaded_at)
);
CREATE TABLE inventario.full_batch_sites(
 batch_id uuid NOT NULL REFERENCES inventario.full_batches(id),sede_id uuid NOT NULL REFERENCES public.sedes(id),
 state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','rejected','confirmed','excluded')),
 snapshot_id uuid,last_error_code text,confirmed_at timestamptz,PRIMARY KEY(batch_id,sede_id)
);
CREATE TABLE inventario.full_operations(
 snapshot_id uuid PRIMARY KEY,batch_id uuid NOT NULL,sede_id uuid NOT NULL,
 fingerprint_version integer NOT NULL DEFAULT 1 CHECK(fingerprint_version=1),fingerprint text NOT NULL,
 state text NOT NULL CHECK(state IN ('rejected','confirmed')),result jsonb,attempts integer NOT NULL DEFAULT 1,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(batch_id,sede_id),FOREIGN KEY(batch_id,sede_id) REFERENCES inventario.full_batch_sites(batch_id,sede_id)
);
ALTER TABLE inventario.snapshots ADD COLUMN full_batch_id uuid REFERENCES inventario.full_batches(id);
CREATE UNIQUE INDEX snapshots_full_batch_site ON inventario.snapshots(full_batch_id,sede_id) WHERE full_batch_id IS NOT NULL;
CREATE UNIQUE INDEX snapshots_legacy_install_hash ON inventario.snapshots(instalacion_id,excel_hash) WHERE full_batch_id IS NULL;
-- The original installation+hash constraint is intentionally retained until coordinated cutover.
CREATE TABLE inventario.full_group_history(
 snapshot_id uuid NOT NULL REFERENCES inventario.snapshots(id),group_id uuid NOT NULL,
 groups_revision bigint NOT NULL,group_name text NOT NULL,category_id uuid NOT NULL,category_name text NOT NULL,
 price numeric NOT NULL,units_per_package integer,package_price numeric,member_codes integer[] NOT NULL,
 members jsonb NOT NULL,stock_theoretical bigint NOT NULL CHECK(stock_theoretical BETWEEN -9007199254740991 AND 9007199254740991),
 PRIMARY KEY(snapshot_id,group_id)
);
CREATE TABLE inventario.full_intervals(
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,sede_id uuid NOT NULL REFERENCES public.sedes(id),c_interno integer NOT NULL,
 snapshot_id uuid NOT NULL REFERENCES inventario.snapshots(id),previous_snapshot_id uuid REFERENCES inventario.snapshots(id),
 captured_at timestamptz NOT NULL,previous_captured_at timestamptz,previous_stock integer,current_stock integer NOT NULL,
 variation bigint,duration_seconds bigint,comparable boolean NOT NULL,quality_reason text,
 algorithm_version text NOT NULL DEFAULT 'full-20-v1',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(snapshot_id,c_interno),CHECK(NOT comparable OR (duration_seconds>0 AND variation>=0))
);
CREATE INDEX full_intervals_sku_capture ON inventario.full_intervals(sede_id,c_interno,captured_at DESC);
CREATE INDEX full_intervals_retention ON inventario.full_intervals(captured_at);
CREATE INDEX full_intervals_previous_snapshot ON inventario.full_intervals(previous_snapshot_id) WHERE previous_snapshot_id IS NOT NULL;
CREATE INDEX full_batches_actor ON inventario.full_batches(installation_id,created_at DESC);
CREATE INDEX full_batches_catalog ON inventario.full_batches(catalog_version);
CREATE INDEX full_operations_batch ON inventario.full_operations(batch_id,state);
CREATE TABLE inventario.full_session_windows(
 session_id uuid PRIMARY KEY REFERENCES inventario.conteos(id),policy_version integer NOT NULL,
 reference_snapshot_id uuid NOT NULL REFERENCES inventario.snapshots(id),reference_captured_at timestamptz NOT NULL,
 capture_interval_number integer NOT NULL CHECK(capture_interval_number IN (1,2)),
 capture_interval_starts_at timestamptz NOT NULL,capture_interval_ends_at timestamptz NOT NULL,
 session_expires_at timestamptz NOT NULL,pending_delivery_until timestamptz NOT NULL,
 CHECK(capture_interval_starts_at<session_expires_at AND session_expires_at<=capture_interval_ends_at AND pending_delivery_until=session_expires_at+interval '2 hours')
);
ALTER TABLE inventario.metrics_movimiento_sku ADD COLUMN algorithm_version text NOT NULL DEFAULT 'legacy-5-v1';
CREATE INDEX full_session_windows_reference ON inventario.full_session_windows(reference_snapshot_id);
CREATE INDEX full_site_permissions_site ON inventario.full_site_permissions(sede_id);
CREATE INDEX full_batch_sites_site ON inventario.full_batch_sites(sede_id);
ALTER TABLE inventario.metrics_calibracion_c24 ADD COLUMN algorithm_version text NOT NULL DEFAULT 'legacy-5-v1';

CREATE FUNCTION inventario.full_utc_v1(p_at timestamptz) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT to_char(p_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
$$;
CREATE FUNCTION inventario.full_window_v1(p_capture timestamptz,p_start timestamptz,p_now timestamptz DEFAULT clock_timestamp()) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path='' AS $$
DECLARE local_start timestamp;shift_begin timestamptz;shift_end timestamptz;h integer;n integer;ends timestamptz;fresh boolean;
BEGIN
 IF p_capture IS NULL OR p_start IS NULL OR p_now IS NULL OR NOT isfinite(p_capture) OR NOT isfinite(p_start) OR NOT isfinite(p_now) THEN RAISE EXCEPTION 'INVALID_OBSERVATION_TIME'; END IF;
 local_start:=p_start AT TIME ZONE 'America/Lima';h:=extract(hour FROM local_start)::integer/8;
 shift_begin:=(date_trunc('day',local_start)+make_interval(hours=>h*8)) AT TIME ZONE 'America/Lima';shift_end:=shift_begin+interval '8 hours';
 fresh:=p_start>=p_capture AND p_start<p_capture+interval '2 hours';
 n:=CASE WHEN p_start<p_capture+interval '1 hour' THEN 1 ELSE 2 END;
 ends:=CASE WHEN fresh THEN least(p_capture+make_interval(hours=>n),shift_end) ELSE NULL END;
 RETURN jsonb_build_object('can_start',fresh,'capture_interval_number',CASE WHEN fresh THEN n ELSE NULL END,
 'capture_interval_starts_at',CASE WHEN fresh THEN inventario.full_utc_v1(p_capture+make_interval(hours=>n-1)) ELSE NULL END,
 'session_expires_at',inventario.full_utc_v1(ends),'stock_expires_at',inventario.full_utc_v1(p_capture+interval '2 hours'),
 'pending_delivery_until',inventario.full_utc_v1(ends+interval '2 hours'),
 'capture_allowed',coalesce(fresh AND p_now>=p_start AND p_now<ends,false),
 'pending_delivery_allowed',coalesce(fresh AND p_now>=p_start AND p_now<ends+interval '2 hours',false),
 'shift',jsonb_build_object('id',(ARRAY['early','day','night'])[h+1],'label','shift_'||(h+1)::text,'starts_at',inventario.full_utc_v1(shift_begin),'ends_at',inventario.full_utc_v1(shift_end)));
END $$;

CREATE FUNCTION inventario.full_retention_candidates_v1(p_asof timestamptz DEFAULT clock_timestamp()) RETURNS SETOF bigint LANGUAGE sql STABLE SET search_path='' AS $$
 SELECT i.id FROM inventario.full_intervals i
 WHERE i.captured_at<p_asof-interval '45 days'
 AND NOT EXISTS(SELECT 1 FROM inventario.conteos c WHERE c.snapshot_referencia_id IN (i.snapshot_id,i.previous_snapshot_id)
   AND c.estado<>'finalizado' AND c.expira_at+interval '2 hours'>p_asof)
 AND NOT EXISTS(SELECT 1 FROM inventario.conteo_detalle cd WHERE cd.snapshot_referencia_id IN (i.snapshot_id,i.previous_snapshot_id)
   OR cd.primer_snapshot_posterior_id IN (i.snapshot_id,i.previous_snapshot_id) OR cd.snapshot_posterior_id IN (i.snapshot_id,i.previous_snapshot_id) OR cd.snapshot_reconteo_id IN (i.snapshot_id,i.previous_snapshot_id))
 AND NOT EXISTS(SELECT 1 FROM inventario.solog_session_runtime_groups r JOIN inventario.conteos c ON c.id=r.conteo_id
   WHERE r.snapshot_referencia_id IN (i.snapshot_id,i.previous_snapshot_id) AND c.expira_at+interval '2 hours'>p_asof)
 AND NOT EXISTS(SELECT 1 FROM inventario.full_session_windows w WHERE w.reference_snapshot_id IN(i.snapshot_id,i.previous_snapshot_id) AND w.pending_delivery_until>p_asof)
$$;
-- Selection only: no destructive retention job is scheduled in these phases.
DO $$ DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['full_settings','full_contracts','full_site_permissions','full_catalog_receipts','full_commands','full_batches','full_batch_sites','full_operations','full_group_history','full_intervals','full_session_windows'] LOOP
  EXECUTE format('ALTER TABLE inventario.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON inventario.%I FROM PUBLIC,anon,authenticated,service_role',t);
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION inventario.full_utc_v1(timestamptz),inventario.full_window_v1(timestamptz,timestamptz,timestamptz),inventario.full_retention_candidates_v1(timestamptz) FROM PUBLIC,anon,authenticated,service_role;








