INSERT INTO inventario.full_contracts VALUES('policy','{"contract_version":1,"snapshot_contract_version":2,"timezone":"America/Lima","recommended_capture_interval_seconds":3600,"minimum_capture_interval_seconds":0,"stock_validity_seconds":7200,"session_capture_interval_seconds":3600,"max_capture_intervals_per_snapshot":2,"pending_delivery_seconds":7200,"observation_future_tolerance_seconds":30,"movement_max_intervals":20,"movement_min_valid_intervals":3,"movement_max_age_seconds":604800,"raw_interval_retention_days":45,"max_body_bytes":4194304,"max_sku_entries":10000,"max_incidents":20000,"max_batch_items":500,"max_response_errors":100,"max_string_length":1024,"automatic_retry_attempts":3,"retry_delays_seconds":[2,5,15],"retry_jitter_fraction":0.2,"rate_limit_requests_per_installation_per_minute":120,"db_lock_timeout_ms":5000,"db_statement_timeout_ms":25000,"http_client_timeout_ms":60000,"shifts_local":[{"id":"early","label":"shift_1","start":"00:00","end":"08:00"},{"id":"day","label":"shift_2","start":"08:00","end":"16:00"},{"id":"night","label":"shift_3","start":"16:00","end":"24:00"}],"retention_capacity_gate":"must_pass_before_activation","kill_switches":{"full_new_ingestion":false,"solog_new_sessions":false},"strict_unknown_properties":true,"fingerprint_version":1}'::jsonb);
ALTER TABLE inventario.metrics_movimiento_sku DROP CONSTRAINT metrics_movimiento_arrays_validos;
ALTER TABLE inventario.metrics_movimiento_sku ADD CONSTRAINT metrics_movimiento_arrays_validos CHECK (cardinality(variacion_stock) = cardinality(duracion_intervalo) AND cardinality(variacion_stock) <= 20 AND COALESCE(array_ndims(variacion_stock), 1) = 1 AND COALESCE(array_ndims(duracion_intervalo), 1) = 1 AND array_position(variacion_stock, NULL::integer) IS NULL AND array_position(duracion_intervalo, NULL::integer) IS NULL AND (0 <= ALL (variacion_stock)) AND (0 < ALL (duracion_intervalo)));
ALTER TABLE inventario.metrics_calibracion_c24 DROP CONSTRAINT metrics_calibracion_c24_valida;
ALTER TABLE inventario.metrics_calibracion_c24 ADD CONSTRAINT metrics_calibracion_c24_valida CHECK (intervalos_validos >= 0 AND intervalos_validos <= 20 AND (calidad = ANY (ARRAY['medido'::text, 'insuficiente'::text, 'caducado'::text, 'invalidado'::text])) AND (c24_sku IS NULL OR c24_sku >= 0::numeric) AND (calidad = 'medido'::text) = (c24_sku IS NOT NULL) AND (calidad <> 'medido'::text OR intervalos_validos >= 3));
CREATE OR REPLACE FUNCTION inventario.full_movement_apply_v1(p_snapshot_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_sede_id uuid;
  v_capturado_at timestamptz;
  v_version_catalogo integer;
  v_actualizados integer;
BEGIN
  SELECT s.sede_id,s.capturado_at,s.version_catalogo
  INTO v_sede_id,v_capturado_at,v_version_catalogo
  FROM inventario.snapshots s
  WHERE s.id=p_snapshot_id AND s.estado='procesando';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'SOLOG_METRICS_SNAPSHOT_NOT_PROCESSING';
  END IF;

  -- Precondición estructural: no calcular variaciones tras reemplazar stock_actual.
  IF EXISTS(
    SELECT 1 FROM inventario.stock_actual a
    WHERE a.sede_id=v_sede_id AND a.snapshot_id=p_snapshot_id
  ) THEN
    RAISE EXCEPTION 'SOLOG_METRICS_SNAPSHOT_STOCK_ALREADY_APPLIED';
  END IF;


  IF NOT EXISTS(SELECT 1 FROM inventario.full_settings WHERE id AND raw_history_enabled AND retention_capacity_verified) THEN RAISE EXCEPTION 'INGESTION_PAUSED'; END IF;
  INSERT INTO inventario.full_intervals(sede_id,c_interno,snapshot_id,previous_snapshot_id,captured_at,previous_captured_at,previous_stock,current_stock,variation,duration_seconds,comparable,quality_reason)
  SELECT v_sede_id,s.c_interno,p_snapshot_id,a.snapshot_id,v_capturado_at,a.observed_at,a.stock,s.stock,
   CASE WHEN a.snapshot_id IS NOT NULL THEN abs(s.stock::bigint-a.stock::bigint) END,
   CASE WHEN a.snapshot_id IS NOT NULL THEN extract(epoch FROM(v_capturado_at-a.observed_at))::bigint END,
   (a.snapshot_id IS NOT NULL AND NOT a.producto_eliminado AND NOT s.producto_eliminado AND m.ultimo_stock IS NOT NULL AND a.snapshot_id=m.ultimo_snapshot_id AND a.observed_at=m.ultimo_capturado_at AND v_capturado_at>m.ultimo_capturado_at AND abs(s.stock::bigint-m.ultimo_stock::bigint)<=2147483647) IS TRUE,
   CASE WHEN s.producto_eliminado OR a.producto_eliminado THEN 'product_absent' WHEN a.snapshot_id IS NULL THEN 'baseline' WHEN m.ultimo_stock IS NULL OR a.snapshot_id IS DISTINCT FROM m.ultimo_snapshot_id OR a.observed_at IS DISTINCT FROM m.ultimo_capturado_at THEN 'baseline_mismatch' WHEN abs(s.stock::bigint-m.ultimo_stock::bigint)>2147483647 THEN 'variation_overflow' WHEN v_capturado_at<=m.ultimo_capturado_at THEN 'nonpositive_duration' ELSE NULL END
  FROM inventario.snapshot_stock s LEFT JOIN inventario.stock_actual a ON a.sede_id=v_sede_id AND a.c_interno=s.c_interno
  LEFT JOIN inventario.metrics_movimiento_sku m ON m.sede_id=v_sede_id AND m.c_interno=s.c_interno
  WHERE s.snapshot_id=p_snapshot_id ON CONFLICT(snapshot_id,c_interno) DO NOTHING;
  WITH entrantes AS MATERIALIZED (
    SELECT ss.c_interno,ss.stock,ss.producto_eliminado,
           v_sede_id AS sede_id, v_capturado_at AS capturado_at,
           p_snapshot_id AS snapshot_id
    FROM inventario.snapshot_stock ss
    JOIN inventario.catalogo_version_skus cvs
      ON cvs.version=v_version_catalogo
     AND cvs.c_interno=ss.c_interno
     AND cvs.estado='incluido'
    JOIN inventario.catalogo c ON c.c_interno=ss.c_interno
     AND c.estado<>'Excluido'
    WHERE ss.snapshot_id=p_snapshot_id
      AND NOT EXISTS(
        SELECT 1 FROM inventario.metrics_movimiento_sku already
        WHERE already.sede_id=v_sede_id AND already.c_interno=ss.c_interno
          AND already.ultimo_snapshot_procesado_id=p_snapshot_id
      )
  ),
  antecedentes AS (
    SELECT e.*,
           m.ultimo_stock,m.ultimo_snapshot_id,m.ultimo_capturado_at,
           m.variacion_stock,m.duracion_intervalo,
           sa.stock AS stock_anterior,sa.snapshot_id AS snapshot_anterior,
           sa.observed_at AS captura_anterior,
           sa.producto_eliminado AS anterior_no_observado,
           (
             NOT e.producto_eliminado
             AND m.ultimo_stock IS NOT NULL
             AND sa.snapshot_id=m.ultimo_snapshot_id
             AND sa.observed_at=m.ultimo_capturado_at
             AND sa.producto_eliminado IS FALSE
             AND e.capturado_at>m.ultimo_capturado_at
             AND abs(e.stock::bigint-m.ultimo_stock::bigint)<=2147483647::bigint
           ) IS TRUE AS comparable
    FROM entrantes e
    LEFT JOIN inventario.metrics_movimiento_sku m
      ON m.sede_id=e.sede_id AND m.c_interno=e.c_interno
    LEFT JOIN inventario.stock_actual sa
      ON sa.sede_id=e.sede_id AND sa.c_interno=e.c_interno
  ),
  arrays AS (
    SELECT a.*,
      CASE WHEN a.comparable THEN
        coalesce(a.variacion_stock,'{}'::integer[])
        || ARRAY[abs(a.stock::bigint-a.ultimo_stock::bigint)::integer]
      ELSE '{}'::integer[] END AS deltas_ext,
      CASE WHEN a.comparable THEN
        coalesce(a.duracion_intervalo,'{}'::integer[])
        || ARRAY[extract(epoch FROM (a.capturado_at-a.ultimo_capturado_at))::integer]
      ELSE '{}'::integer[] END AS segundos_ext
    FROM antecedentes a
  ),
  preparados AS (
    SELECT a.*,
      ARRAY(
        SELECT x.v FROM pg_catalog.unnest(a.deltas_ext)
        WITH ORDINALITY AS x(v,pos)
        WHERE x.pos>greatest(pg_catalog.cardinality(a.deltas_ext)-20,0)
        ORDER BY x.pos
      ) AS deltas20,
      ARRAY(
        SELECT x.v FROM pg_catalog.unnest(a.segundos_ext)
        WITH ORDINALITY AS x(v,pos)
        WHERE x.pos>greatest(pg_catalog.cardinality(a.segundos_ext)-20,0)
        ORDER BY x.pos
      ) AS segundos20
    FROM arrays a
  )
  INSERT INTO inventario.metrics_movimiento_sku(
    sede_id,c_interno,variacion_stock,duracion_intervalo,
    ultimo_stock,ultimo_snapshot_id,ultimo_capturado_at,
    ultimo_snapshot_procesado_id,c24_sku,estado_calidad,updated_at
  )
  SELECT p.sede_id,p.c_interno,p.deltas20,p.segundos20,
         CASE WHEN p.producto_eliminado THEN NULL ELSE p.stock END,
         CASE WHEN p.producto_eliminado THEN NULL ELSE p.snapshot_id END,
         CASE WHEN p.producto_eliminado THEN NULL ELSE p.capturado_at END,
         p.snapshot_id,
         CASE WHEN p.producto_eliminado THEN NULL ELSE c.c24_sku END,
         CASE WHEN p.producto_eliminado THEN 'insuficiente'
              WHEN pg_catalog.cardinality(p.deltas20)=0 THEN 'base'
              WHEN c.c24_sku IS NULL THEN 'insuficiente'
              ELSE 'medido' END,
         pg_catalog.clock_timestamp()
  FROM preparados p
  CROSS JOIN LATERAL inventario.metrics_c24_ventana_v1(
    p.deltas20,p.segundos20,
    CASE WHEN p.producto_eliminado THEN NULL ELSE p.capturado_at END,
    p.capturado_at
  ) c
  ON CONFLICT(sede_id,c_interno) DO UPDATE SET
    variacion_stock=EXCLUDED.variacion_stock,
    duracion_intervalo=EXCLUDED.duracion_intervalo,
    ultimo_stock=EXCLUDED.ultimo_stock,
    ultimo_snapshot_id=EXCLUDED.ultimo_snapshot_id,
    ultimo_capturado_at=EXCLUDED.ultimo_capturado_at,
    ultimo_snapshot_procesado_id=EXCLUDED.ultimo_snapshot_procesado_id,
    c24_sku=EXCLUDED.c24_sku,
    estado_calidad=EXCLUDED.estado_calidad,
    updated_at=EXCLUDED.updated_at;

  GET DIAGNOSTICS v_actualizados=ROW_COUNT;
  UPDATE inventario.metrics_movimiento_sku SET algorithm_version='full-20-v1' WHERE sede_id=v_sede_id AND ultimo_snapshot_procesado_id=p_snapshot_id;
  RETURN v_actualizados;
END;
$function$;

CREATE OR REPLACE FUNCTION inventario.metrics_movimiento_snapshot_stock_hook_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_id uuid;
BEGIN
  IF TG_OP<>'INSERT' OR TG_LEVEL<>'STATEMENT' THEN
    RAISE EXCEPTION 'SOLOG_METRICS_INVALID_TRIGGER_CONTEXT';
  END IF;
  FOR v_id IN
    SELECT DISTINCT n.snapshot_id
    FROM metrics_new_snapshot_rows n
    JOIN inventario.snapshots s ON s.id=n.snapshot_id
    WHERE s.estado='procesando'
  LOOP
    IF EXISTS(SELECT 1 FROM inventario.snapshots WHERE id=v_id AND full_batch_id IS NOT NULL) THEN
      PERFORM inventario.full_movement_apply_v1(v_id);
    ELSE PERFORM inventario.metrics_movimiento_aplicar_snapshot_v1(v_id); END IF;
  END LOOP;
  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION inventario.full_calibration_sample_v1(p_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_slot timestamptz;
  v_insertados integer;
BEGIN
  IF p_at IS NULL OR p_at>pg_catalog.clock_timestamp()+interval '5 minutes' THEN
    RAISE EXCEPTION 'SOLOG_CALIBRATION_INVALID_TIMESTAMP';
  END IF;
  -- Slot fijo 6h a HH:05 Lima. Un mismo slot se registra una vez.
  v_slot:=pg_catalog.date_bin('6 hours',p_at,
    '2000-01-01 05:05:00+00'::timestamptz);
  INSERT INTO inventario.metrics_calibracion_c24(
    muestreo_at,sede_id,c_interno,grupo_conteo_id,c24_sku,
    intervalos_validos,calidad,ultimo_capturado_at,algorithm_version
  )
  SELECT v_slot,m.sede_id,m.c_interno,c.grupo_conteo_id,
         e.c24_sku,e.intervalos_validos,
         CASE WHEN m.estado_calidad='invalidado' THEN 'invalidado'
              ELSE e.calidad END,
         m.ultimo_capturado_at,m.algorithm_version
  FROM inventario.metrics_movimiento_sku m
  JOIN inventario.catalogo c ON c.c_interno=m.c_interno
    AND c.estado<>'Excluido'
  CROSS JOIN LATERAL inventario.metrics_movimiento_c24_efectivo_v1(
    m.sede_id,m.c_interno,p_at
  ) e
  ON CONFLICT(muestreo_at,sede_id,c_interno) DO NOTHING;
  GET DIAGNOSTICS v_insertados=ROW_COUNT;
  RETURN v_insertados;
END;
$function$;

REVOKE ALL ON FUNCTION inventario.full_movement_apply_v1(uuid),inventario.full_calibration_sample_v1(timestamptz) FROM PUBLIC,anon,authenticated,service_role;
